        return Err(invalid_credentials());
    }
    let now = crate::time::unix_now_secs();
    if now.abs_diff(proof.timestamp) > SOVEREIGN_TIMESTAMP_WINDOW_SECS as u64 {
        return Err(invalid_credentials());
    }

