55	        let long = URL_SAFE_NO_PAD.encode([0u8; NONCE_BYTES + 1]);
56	        assert_eq!(decode_canonical_base64url(&long, NONCE_BYTES), None);
57	
58	        // A well-formed nonce is not a well-formed signature and vice versa.
59	        let nonce = URL_SAFE_NO_PAD.encode([0u8; NONCE_BYTES]);
60	        assert_eq!(decode_canonical_base64url(&nonce, SIGNATURE_BYTES), None);
61	    }
62	
63	    #[test]
64	    fn padded_spelling_of_the_same_bytes_is_rejected() {
65	        // The canonical spelling is unpadded; `=`-padded input decodes to the same bytes under a
66	        // laxer engine, which would make one nonce re-spellable and defeat the replay store.
67	        let padded = format!("{}=", URL_SAFE_NO_PAD.encode([0u8; NONCE_BYTES]));
68	        assert_eq!(decode_canonical_base64url(&padded, NONCE_BYTES), None);
69	    }
70	
71	    #[test]
72	    fn non_canonical_trailing_bits_are_rejected() {
73	        // 32 bytes encode to 43 symbols; the final symbol carries 2 unused low bits. Setting them
74	        // yields a different spelling of the same 32 bytes.
75	        let canonical = URL_SAFE_NO_PAD.encode([0u8; NONCE_BYTES]);
76	        assert!(canonical.ends_with('A'));
77	        let mut respelled = canonical[..canonical.len() - 1].to_string();
78	        respelled.push('B');
79	        assert_ne!(respelled, canonical);
80	        assert_eq!(decode_canonical_base64url(&respelled, NONCE_BYTES), None);
81	    }
82	
83	    #[test]
84	    fn standard_base64_alphabet_and_junk_are_rejected() {
85	        // `+` and `/` are the standard alphabet's substitutes for url-safe `-` and `_`.
86	        let standard =
87	            base64::engine::general_purpose::STANDARD_NO_PAD.encode([0xffu8; NONCE_BYTES]);
88	        assert!(standard.contains('+') || standard.contains('/'));
89	        assert_eq!(decode_canonical_base64url(&standard, NONCE_BYTES), None);
90	
91	        assert_eq!(decode_canonical_base64url("", NONCE_BYTES), None);
92	        assert_eq!(decode_canonical_base64url("not base64!", NONCE_BYTES), None);
93	    }
94	}

